export type TApiAuditLog = Parameters<typeof queueAuditEvent>[0];
export type TApiV1Authentication = TAuthenticationApiKey | Session | null;
export type TApiKeyAuthentication = TAuthenticationApiKey | null;
export type TSessionAuthentication = Session | null;

// Interface for handler function parameters
export interface THandlerParams<TProps = unknown> {
  req: NextRequest;
  props: TProps;
  auditLog?: TApiAuditLog;
  authentication?: TApiV1Authentication;
}

// Interface for wrapper function parameters
export interface TWithV1ApiWrapperParams<
  TResult extends { response: Response; error?: unknown },
  TProps = unknown,
> {
  handler: (params: THandlerParams<TProps>) => Promise<TResult>;
  action?: TAuditAction;
  targetType?: TAuditTarget;
  customRateLimitConfig?: TRateLimitConfig;
  /**
   * When the route requires auth but the client is unauthenticated, the wrapper normally returns
   * the legacy JSON 401. Use this to return a custom response (e.g. RFC 9457 problem+json for V3).
   */
  unauthenticatedResponse?: (req: NextRequest) => Response;
  /**
   * Most v1 management routes are environment-scoped. Enable this only for routes that explicitly
   * support organization-only API keys.
   */

export function buildV3AuditLog(
  authentication: TV3Authentication,
  action?: TAuditAction,
  targetType?: TAuditTarget,
  apiUrl?: string
): TV3AuditLog | undefined {
  if (!authentication || !action || !targetType || !apiUrl) {
    return undefined;
  }

  const auditLog = buildAuditLogBaseObject(action, targetType, apiUrl);

  if ("user" in authentication && authentication.user?.id) {
    auditLog.userId = authentication.user.id;
    auditLog.userType = "user";
  } else if ("apiKeyId" in authentication) {
    auditLog.userId = authentication.apiKeyId;
    auditLog.userType = "api";
    auditLog.organizationId = authentication.organizationId;
  }

  return auditLog;
}

const SKIPPED_AUDIT_LOGS = new WeakSet<TV3AuditLog>();

/**
 * Mark a request's audit entry as not worth recording, for an operation that turned out to change
 * nothing it promises to audit — a visibility no-op (ENG-3282, contract §3). Only a successful no-op
 * should ever be skipped; a refusal stays audited as a failure.
 */

export async function queueV3AuditLog(
  auditLog: TV3AuditLog | undefined,
  requestId: string,
  log: ReturnType<typeof logger.withContext>
): Promise<void> {
  if (!auditLog || SKIPPED_AUDIT_LOGS.has(auditLog)) {
    return;
  }

  try {
    await queueAuditEvent({
      ...auditLog,
      ...(auditLog.status === "failure" ? { eventId: auditLog.eventId ?? requestId } : {}),
    });
  } catch (error) {
    log.error({ error }, "Failed to queue V3 audit event");
  }
}

import { logger } from "@formbricks/logger";
import { type TAuditLogEvent, ZAuditLogEventSchema } from "@/modules/ee/audit-logs/types/audit-log";

const validateEvent = (event: TAuditLogEvent): void => {
  const result = ZAuditLogEventSchema.safeParse(event);
  if (!result.success) {
    throw new Error(`Invalid audit log event: ${result.error.message}`);
  }
};

export const logAuditEvent = async (event: TAuditLogEvent): Promise<void> => {
  try {
    validateEvent(event);
    // Scalar aliases remain directly searchable across log transports without flattening nested fields.
    logger.audit({
      ...event,
      actorId: event.actor.id,
      actorType: event.actor.type,
      targetId: event.target.id,
      targetType: event.target.type,
    });
  } catch (error) {
    // Log error to application logger but don't throw
    // This ensures audit logging failures don't break the application
    logger.error(error, "Failed to log audit event");
  }
};

/**
 * POST /api/v3/responses/batch-delete — delete up to 100 responses in one transaction.
 *
 * A POST custom method rather than a `DELETE` on the collection: a collection-level delete that loses
 * its filters — a client bug, a proxy stripping the query string, a copied curl command — degrades into
 * erasing every response in scope, and a distinct path cannot be reached by accident. AIP-165 blesses
 * `batchDelete` for exactly this reason.
 *
 * A thin adapter on purpose: the orchestration lives in the operation and the service, which the MCP
 * server also calls directly with no wrapper around them.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { batchDeleteV3Responses } from "../lib/operations";
import { ZV3BatchDeleteResponsesBody, ZV3BatchDeleteResponsesQuery } from "../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "deleted",
  targetType: "response",
  schemas: { body: ZV3BatchDeleteResponsesBody, query: ZV3BatchDeleteResponsesQuery },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    batchDeleteV3Responses({
      authentication,
      workspaceId: parsedInput.query.workspaceId,
      ids: parsedInput.body.ids,
      auditLog,
      requestId,
      instance,
    }),
});

import "server-only";
import { logger } from "@formbricks/logger";
import type { TResponseData, TResponseDataValue } from "@formbricks/types/responses";
import { formatZodIssues } from "@/app/api/v3/lib/api-wrapper";
import { requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import { mapV3ThrownError } from "@/app/api/v3/lib/errors";
import { buildKeysetPage } from "@/app/api/v3/lib/keyset-cursor";
import {
  type InvalidParam,
  createdResponse,
  noContentResponse,
  problemBadRequest,
  problemForbidden,
  problemUnprocessableContent,
  successListResponse,
  successResponse,
} from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { buildVisibleSurveyWhere } from "@/lib/survey/visibility/predicate";
import { getWorkspaceLegacyStoragePrefixes } from "@/lib/workspace/service";
import { validateResponseData } from "@/modules/api/lib/validation";
import { validateClientFileUploads } from "@/modules/storage/utils";
import { buildAnswerPlan } from "./answers";
