\"use client\";

import { useMutation, useQuery, useQueryClient } from \"@tanstack/react-query\";
import { TUserLocale } from \"@formbricks/types/user\";
import { getApiKeysWithEnvironmentPermissions } from \"@/modules/organization/settings/api-keys/lib/api-key\";
import { TOrganizationWorkspace } from \"@/modules/organization/settings/api-keys/types/api-keys\";
import { EditAPIKeys } from \"./edit-api-keys\";

const API_KEYS_QUERY_KEY = [\"api-keys\"];

interface ApiKeyListProps {
  organizationId: string;
  locale: TUserLocale;
  workspaces: TOrganizationWorkspace[];
  isFormbricksCloud: boolean;
  canGrantOrganizationWriteAccess: boolean;
}

export const ApiKeyList = ({
  organizationId,
  locale,
  workspaces,
  isFormbricksCloud,
  canGrantOrganizationWriteAccess,
}: Readonly<ApiKeyListProps>) => {
  const queryClient = useQueryClient();

  const { data: apiKeys = [] } = useQuery({
    queryKey: [...API_KEYS_QUERY_KEY, organizationId],
    queryFn: () => getApiKeysWithEnvironmentPermissions(organizationId),
    initialData: [],
  });

  const deleteMutation = useMutation({
    mutationFn: async (apiKeyId: string) => {
      const { deleteApiKeyAction } = await import(\"../actions\");
      const result = await deleteApiKeyAction({ id: apiKeyId });
      if ("'!result?.data) {
        throw new Error("Failed to delete API key");
      }
      return result;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
    },
  });

  const createMutation = useMutation({
    mutationFn: async (apiKeyData: {
      label: string;
      workspacePermissions: Array<{
        permission: import("@formbricks/database/prisma-browser").ApiKeyPermission;
        workspaceId: string;
      }>;
      organizationAccess: import("@formbricks/types/api-key").TOrganizationAccess;
    }) => {
      const { createApiKeyAction } = await import("../actions");
      const result = await createApiKeyAction({
        organizationId,
        apiKeyData,
      });
      if (!result?.data) {
        throw new Error("Failed to create API key");
      }
      return result;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({
      apiKeyId,
      apiKeyData,
    }: {
      apiKeyId: string;
      apiKeyData: import("../types/api-keys").TApiKeyUpdateInput;
    }) => {
      const { updateApiKeyAction } = await import("../actions");
      const result = await updateApiKeyAction({
        apiKeyId,
        apiKeyData,
      });
      if (!result?.data) {
        throw new Error("Failed to update API key");
      }
      return result;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: API_KEYS_QUERY_KEY });
    },
  });

  return (
    <EditAPIKeys
      organizationId={organizationId}
      apiKeys={apiKeys}
      locale={locale}
      workspaces={workspaces}
      isFormbricksCloud={isFormbricksCloud}
      canGrantOrganizationWriteAccess={canGrantOrganizationWriteAccess}
      deleteMutation={deleteMutation}
      createMutation={createMutation}
      updateMutation={updateMutation}
    />
  );
};
APIKEYLIST_EOF'

